from common import *

C = "opioids"
OPIOID_BOXED = lambda n, extra=(): {"boxed": {"title": "FDA boxed warnings", "items": [
    f"{n} exposes users to risks of addiction, misuse, and abuse, which can lead to overdose and death.",
    "Life-threatening slowed breathing can occur, especially when starting treatment or after a dose increase.",
    "Accidental ingestion, especially by children, can cause a fatal overdose.",
    "Use with benzodiazepines or other central nervous system depressants, including alcohol, can cause profound sedation, slowed breathing, coma, and death.",
    "Prolonged use during pregnancy can cause neonatal opioid withdrawal syndrome, which may be life-threatening if not recognized and treated.",
    *extra]}}

def op_ix(name, extra=()):
    return [["Benzodiazepines (alprazolam, diazepam, clonazepam)", "Profound sedation, slowed breathing, coma, death", "Boxed warning; avoid unless no alternative"],
            ["Alcohol", "Stronger sedation and slowed breathing", "Avoid"],
            ["Gabapentin, pregabalin, sleep medicines, muscle relaxants", "Additive sedation and breathing problems", "Use caution; lower doses"],
            *extra,
            ["Other opioids", "Additive breathing suppression", "Avoid unless directed by prescriber"]]

def op_withdrawal(n, onset, peak, lasts, extra=()):
    return {"blocks": [
        {"p": f"People who take {n} regularly for more than a few weeks become physically dependent, even when they take it exactly as prescribed. Dependence is not the same as addiction, but it means stopping suddenly causes withdrawal.[[label]]"},
        {"timeline": [
            {"when": onset, "title": "Early symptoms", "text": "Anxiety, restlessness, yawning, sweating, runny nose, watery eyes, and muscle aches."},
            {"when": peak, "title": "Peak withdrawal", "text": "Diarrhea, stomach cramps, nausea and vomiting, goosebumps, dilated pupils, fast heartbeat, and strong cravings. Rarely dangerous in healthy adults, but dehydration can be serious."},
            {"when": lasts, "title": "Lingering symptoms", "text": "Poor sleep, low mood, low energy, and cravings can continue for weeks. Tolerance falls quickly, which raises the risk of overdose if use restarts."}]},
        {"warn": f"After a break, the body loses tolerance within days. Returning to a previous dose of {n} can cause a fatal overdose."},
        {"p": "The FDA warns against stopping opioids abruptly in people who are physically dependent. A prescriber can taper the dose gradually, often by 10% or less per month for long-term users, and medicines such as clonidine or lofexidine can ease symptoms. For opioid use disorder, buprenorphine and methadone cut the risk of death roughly in half.[[cdc22]]"},
        *extra]}

INTL_OPIOID = lambda uk="Class A; prescription only", ca="Schedule I of the Controlled Drugs and Substances Act; prescription only", au="Schedule 8 controlled drug; prescription only", un="Schedule I of the 1961 Single Convention on Narcotic Drugs": [
    ["United Kingdom", uk], ["Canada", ca], ["Australia", au], ["International", un]]

